import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"敬","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-敬.md","filePath":"50-概念资料/dict-敬.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-敬.md"};function d(i,t,h,c,u,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="敬" tabindex="-1">敬 <a class="header-anchor" href="#敬" aria-label="Permalink to &quot;敬&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：恭敬心 | 道家对应：谦下</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;敬&quot;就是<strong>尊重一切众生</strong>。不是卑微，不是畏惧，而是认识到每个人（包括自己）都有佛性、都值得被认真对待。</p><p>了空居士从释迦牟尼佛托钵时穿袈裟、恭敬面对布施者的细节中提炼出&quot;敬&quot;——连佛陀都如此恭敬，何况我们。敬是修行的入门条件：没有敬，一切方法都无从生效。同时，&quot;许多人以我为师，其实我心中也将我所遇到的每一个人当作师&quot;——敬是双向的。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;世尊著衣持钵…对大众都很恭敬。恭敬不是卑微，是尊重一切众生。&quot; — <a href="/60-原文段落/金刚经1分-恭敬心">金刚经1分-恭敬心</a></p></blockquote><blockquote><p>&quot;修行人最重要的是要有至诚恭敬之心。许多人以我为师，其实我心中也将我所遇到的每一个人当作师啊。&quot; — 论坛语录</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>恭敬就是拍马屁或卑微</td><td>恭敬是平等的尊重，既尊重对方也尊重自己</td></tr><tr><td>只对师父恭敬就够了</td><td>恭敬心是对一切人的，不分别对象</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-处世">dict-处世</a> — 敬是待人处世的基本态度</li><li><a href="/50-概念资料/dict-正">dict-正</a> — 有敬心，行为自然趋正</li><li><a href="/50-概念资料/dict-我执">dict-我执</a> — 敬的反面是我执（觉得自己了不起）</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 恭敬心是日常细节中的修行</li><li><a href="/10-核心模型/model-天人合一">model-天人合一</a> — 以恭敬心与万事万物的场融通</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>对每个人——不管地位高低——都以同样的认真去对待。倾听时看着对方，不打断，不轻视。这就是日常中的&quot;敬&quot;。</p>',16)])])}const b=a(l,[["render",d]]);export{q as __pageData,b as default};
